// Dados do protótipo: croquis "de fábrica" + persistência local (localStorage).
// Sem backend — isso simula um banco só pra dar consistência entre as telas.

const DIRECOES_VEICULAR = [
  "Só frente",
  "Frente + direita",
  "Frente + esquerda",
  "Todas",
  "Só esquerda",
  "Só direita",
  "Direita + esquerda",
];

const STORAGE_KEY = "croqui_prototipo_v1";
const DELETED_KEY = "croqui_prototipo_v1_deleted";
const CONTROLADORES_SOLTOS_KEY = "croqui_prototipo_v1_controladores_soltos";
const BACKUP_CARREGADO_KEY = "croqui_prototipo_v1_backup_carregado";

// --- deploy estático (Vercel): puxa os cadastros do backup-dados.json no 1º acesso ---
// Rodando local, o _serve.ps1 grava esse arquivo a cada alteração e o localStorage é a
// fonte da verdade. Num deploy novo (origem diferente => localStorage vazio) só apareceria
// o seed. Então, SÓ quando ainda não há nada salvo neste navegador, carrega o snapshot do
// arquivo pro localStorage, uma única vez. Depois disso o localStorage manda, como sempre.
// XHR síncrono de propósito: precisa terminar antes de listCroquis()/getCroquiDetail(),
// que rodam assim que o data.js carrega. Qualquer falha (file://, sem rede, storage
// bloqueado) é ignorada — segue com o seed.
(function carregarBackupSeVazio() {
  try {
    if (typeof localStorage === "undefined") return;
    if (localStorage.getItem(STORAGE_KEY) !== null) return;
    if (localStorage.getItem(BACKUP_CARREGADO_KEY) === "1") return;
    const x = new XMLHttpRequest();
    x.open("GET", "/backup-dados.json", false);
    x.send();
    if (x.status === 200) {
      const b = JSON.parse(x.responseText);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(b.overrides || {}));
      localStorage.setItem(DELETED_KEY, JSON.stringify(b.deletados || []));
    }
    localStorage.setItem(BACKUP_CARREGADO_KEY, "1");
  } catch (e) {
    /* sem backup acessível — segue com os dados de fábrica */
  }
})();

