// Controladores do seed que o usuário já vinculou a um croqui (ou removeu do pool). Fica
// à parte do CONTROLADORES_SOLTOS_KEY porque agora o read faz merge do seed com o que está
// salvo — sem esta lista, um controlador vinculado voltaria a aparecer no próximo load.
const CONTROLADORES_SEED_REMOVIDOS_KEY = "croqui_prototipo_v1_controladores_seed_removidos";

function readSeedRemovidos() {
  try {
    return new Set(JSON.parse(localStorage.getItem(CONTROLADORES_SEED_REMOVIDOS_KEY)) || []);
  } catch {
    return new Set();
  }
}

function marcarSeedRemovido(id) {
  const s = readSeedRemovidos();
  s.add(id);
  try {
    localStorage.setItem(CONTROLADORES_SEED_REMOVIDOS_KEY, JSON.stringify(Array.from(s)));
  } catch {
    // sem espaço/indisponível — o filtro em readControladoresSoltos ainda vale nesta sessão
  }
}

function readControladoresSoltos() {
  let salvos = null;
  try {
    const raw = localStorage.getItem(CONTROLADORES_SOLTOS_KEY);
    if (raw) salvos = JSON.parse(raw);
  } catch {
    salvos = null;
  }

  // Nada salvo neste navegador ainda: usa o seed puro.
  if (!Array.isArray(salvos)) {
    return JSON.parse(JSON.stringify(CONTROLADORES_SEM_CROQUI_SEED));
  }

  // Já existe lista salva (o usuário criou / moveu / vinculou controladores). NÃO
  // sobrescreve nada dela — só acrescenta os controladores do seed que ela ainda não tem
  // (ex.: a leva de São José dos Pinhais adicionada depois). Entradas salvas vencem as do
  // seed de mesmo id, pra preservar posição movida e qualquer dado do usuário; e o que já
  // foi vinculado/removido (readSeedRemovidos) não volta.
  const removidos = readSeedRemovidos();
  const porId = new Map(salvos.map((c) => [c.id, c]));
  for (const s of CONTROLADORES_SEM_CROQUI_SEED) {
    if (!porId.has(s.id) && !removidos.has(s.id)) {
      porId.set(s.id, JSON.parse(JSON.stringify(s)));
    }
  }
  return Array.from(porId.values());
}

function writeControladoresSoltos(lista) {
  try {
    localStorage.setItem(CONTROLADORES_SOLTOS_KEY, JSON.stringify(lista));
  } catch {
    // sem espaço/indisponível — sem problema, é só o pool de demonstração
  }
}

// Tira um controlador do pool de "soltos" quando ele é vinculado a um croqui — some do
// mapa dos outros croquis depois disso (não fica oferecendo o mesmo controlador de novo).
function removerControladorSolto(id) {
  writeControladoresSoltos(readControladoresSoltos().filter((c) => c.id !== id));
  marcarSeedRemovido(id); // impede o merge do seed de trazer de volta um controlador já vinculado
}

