function readOverrides() {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEY)) || {};
  } catch {
    return {};
  }
}

// Além do localStorage (que pode sumir se limpar o navegador, trocar de máquina etc.),
// manda um snapshot completo pro servidor local gravar em disco (_serve.ps1, POST
// /api/backup → backup-dados.json na raiz do projeto). "Fire and forget": se o servidor
// não estiver rodando ou não suportar POST (ex.: aberto direto via file://), ignora — o
// localStorage continua funcionando normalmente, isso é só uma segurança a mais.
//
// Debounced de propósito: gravações em rajada (ex. importar/gerar vários croquis
// seguidos) disparavam um POST por gravação, e como cada um é uma requisição HTTP
// separada, a ordem de CHEGADA no servidor não é garantida — um POST mais antigo podia
// terminar depois de um mais novo e sobrescrever o arquivo com um snapshot desatualizado
// (foi exatamente isso que deixou o backup.json incompleto certa vez). Esperando um
// instante de silêncio antes de mandar, só sai UM POST por rajada, sempre com o estado
// mais atual (readOverrides() é lido na hora de disparar, não na hora de agendar).
let backupDebounceTimer = null;
// O fetch acima é "fire and forget" — se o servidor local não estiver rodando (ou o POST
// falhar por qualquer motivo), a Promise rejeita. Antes do Supabase (ver
// assets/supabase-sync.js) isso avisava com um toast, porque o backup-dados.json local
// era a única rede de segurança de verdade. Agora os dados de posição já vão pro Supabase
// em paralelo (um banco de verdade, sobrevive a limpar o navegador/trocar de máquina) —
// esse backup em disco virou só um espelho extra, não crítico. Log discreto no console em
// vez de toast, pra não alarmar por algo que não é mais o principal ponto de falha.
function enviarBackupParaArquivo() {
  clearTimeout(backupDebounceTimer);
  backupDebounceTimer = setTimeout(() => {
    salvarBackupAgora().catch(() => {
      console.warn("Backup em disco (backup-dados.json) falhou — sem problema, os dados de posição já estão no Supabase. Só afeta o espelho local em disco.");
    });
  }, 400);
}

// Mesmo POST de sempre, mas disparado na hora (sem esperar o debounce) e retornando a
// Promise — usado pelo botão manual "Salvar backup", que precisa saber se deu certo pra
// avisar o usuário, diferente do fire-and-forget automático de cada gravação.
function salvarBackupAgora() {
  try {
    return fetch("/api/backup", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ overrides: readOverrides(), deletados: Array.from(readDeletedIds()) }),
    }).then((res) => {
      if (!res.ok) throw new Error(`backup respondeu ${res.status}`);
      return res;
    });
  } catch {
    // fetch nem existe (ex.: file://) — sem problema, é só a camada extra de segurança
    return Promise.reject(new Error("fetch indisponível"));
  }
}

function writeOverride(croqui) {
  const overrides = readOverrides();
  overrides[croqui.id] = croqui;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(overrides));
  } catch (err) {
    showToast("Não deu pra salvar — armazenamento local cheio (anexos ou fotos grandes?).");
  }
  enviarBackupParaArquivo();
  // Chave liga/desliga — ver assets/supabase-sync.js.
  if (typeof agendarEnvioSupabase === "function") agendarEnvioSupabase(croqui);
}

function readDeletedIds() {
  try {
    return new Set(JSON.parse(localStorage.getItem(DELETED_KEY)) || []);
  } catch {
    return new Set();
  }
}

// Apaga um croqui (base "de fábrica" ou criado no protótipo). Como não há backend,
// croquis base não somem do array BASE_CROQUIS — ficam marcados como apagados numa
// lista à parte, e listCroquis()/getCroquiDetail() passam a ignorá-los.
function deleteCroqui(id) {
  const overrides = readOverrides();
  delete overrides[id];
  localStorage.setItem(STORAGE_KEY, JSON.stringify(overrides));

  const deleted = readDeletedIds();
  deleted.add(id);
  localStorage.setItem(DELETED_KEY, JSON.stringify(Array.from(deleted)));
  enviarBackupParaArquivo();
}

// Restaura o localStorage a partir do backup-dados.json salvo em disco — usado quando os
// dados do navegador somem (cache limpo, outro navegador/máquina). Substitui tudo que
// está salvo agora, por isso pede confirmação antes de chamar (ver index.html, a listagem).
async function restaurarBackupDoArquivo() {
  const res = await fetch("/backup-dados.json", { cache: "no-store" });
  if (!res.ok) throw new Error("Backup não encontrado.");
  const backup = await res.json();
  localStorage.setItem(STORAGE_KEY, JSON.stringify(backup.overrides || {}));
  localStorage.setItem(DELETED_KEY, JSON.stringify(backup.deletados || []));
}

// Lista pra tela de listagem: mescla base + qualquer edição/criação salva, menos apagados.
function listCroquis() {
  const overrides = readOverrides();
  const deleted = readDeletedIds();
  const byId = new Map(BASE_CROQUIS.map((c) => [c.id, c]));
  Object.values(overrides).forEach((c) => byId.set(c.id, c));
  return Array.from(byId.values())
    // "ativo" só existe em croquis desativados (registro antigo sem o campo = ativo).
    .filter((c) => !deleted.has(c.id) && c.ativo !== false)
    .map((c) => ({
      id: c.id,
      nome: c.nome,
      lat: c.lat,
      lng: c.lng,
      atualizado: c.atualizado,
      controladores: (c.controladores || []).length,
      // ID do primeiro controlador — usado como prefixo no seletor de croqui do editor
      // (ex.: "CT-2100 · Rua x Rua"), pra achar pelo número do controlador, não só pelo nome.
      controladorId: (c.controladores || [])[0]?.id || null,
      gruposVeicular: (c.grupos || []).filter((g) => g.tipo === "veicular").length,
      gruposPedestre: (c.grupos || []).filter((g) => g.tipo === "pedestre").length,
    }));
}

// Detalhe completo pro Editor. id vazio/nulo = croqui novo (template em branco).
function getCroquiDetail(id) {
  if (!id) {
    return {
      id: null,
      nome: "",
      lat: -25.4296, lng: -49.2719, // centro de Curitiba, ponto de partida genérico
      controladores: [],
      area: null,
      grupos: [],
      textos: [],
    };
  }
  const overrides = readOverrides();
  if (overrides[id]) return JSON.parse(JSON.stringify(overrides[id]));
  const base = BASE_CROQUIS.find((c) => c.id === id);
  return base ? JSON.parse(JSON.stringify(base)) : getCroquiDetail(null);
}

function saveCroquiDetail(detail) {
  if (!detail.id) {
    const n = Math.floor(1000 + Math.random() * 9000);
    detail.id = `CRQ-${n}`;
  }
  detail.atualizado = new Date().toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit" }) +
    " " + new Date().toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });
  writeOverride(detail);
  return detail.id;
}
